<?php require 'config.php'; $roll=trim($_GET['roll_no']??'');$student=null;$rows=[];if($roll!==''){$stmt=$conn->prepare('SELECT * FROM students WHERE roll_no=?');$stmt->bind_param('s',$roll);$stmt->execute();$student=$stmt->get_result()->fetch_assoc();if($student){$stmt=$conn->prepare('SELECT su.subject_code,su.subject_name,su.max_marks,su.pass_marks,m.marks_obtained FROM subjects su LEFT JOIN marks m ON m.subject_id=su.id AND m.student_id=? ORDER BY su.subject_name');$stmt->bind_param('i',$student['id']);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);}}$page_title='Result'; require 'header.php'; ?>
<div class="result-wrap"><?php if(!$student):?><div class="panel empty"><h1>Result not found</h1><p>Check the roll number and try again.</p><a class="button-link" href="index.php">Back to search</a></div><?php else: $total=0;$maximum=0;$passed=true;foreach($rows as $r){$total+=(float)($r['marks_obtained']??0);$maximum+=$r['max_marks'];if($r['marks_obtained']===null||(float)$r['marks_obtained']<$r['pass_marks'])$passed=false;} $percentage=$maximum?($total/$maximum*100):0;?><section class="result-card"><div class="result-top"><div><p class="eyebrow">Official Result</p><h1><?=e($student['name'])?></h1><p><?=e($student['roll_no'])?> · <?=e($student['class_name'])?></p></div><div class="final <?= $passed?'pass':'fail' ?>"><span>Final Result</span><strong><?= $passed?'PASS':'FAIL' ?></strong></div></div><table class="result-table"><tr><th>Code</th><th>Subject</th><th>Max Marks</th><th>Marks Obtained</th><th>Status</th></tr><?php foreach($rows as $r):$ok=$r['marks_obtained']!==null&&(float)$r['marks_obtained']>=$r['pass_marks'];?><tr><td><?=e($r['subject_code'])?></td><td><?=e($r['subject_name'])?></td><td><?=$r['max_marks']?></td><td><?= $r['marks_obtained']===null?'—':$r['marks_obtained']?></td><td><span class="badge <?=$ok?'ok':'no'?>"><?=$ok?'Pass':'Fail'?></span></td></tr><?php endforeach;?></table><div class="summary"><div><span>Total Marks</span><strong><?=$total?> / <?=$maximum?></strong></div><div><span>Percentage</span><strong><?=number_format($percentage,2)?>%</strong></div><div><span>Grade</span><strong><?=grade($percentage)?></strong></div></div><button class="print" onclick="window.print()">Print Result</button></section><?php endif;?></div>
<?php require 'footer.php'; ?>
